  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch.get(\"log_prob_w\", None)\n    lpl = batch.get(\"log_prob_l\", None)\n    weight = batch.get(\"weight\", None)\n    cost_gap = batch.get(\"cost_gap\", None)\n    if lpw is None or lpl is None or weight is None or cost_gap is None:\n        raise KeyError(\"Required keys missing in batch\")\n    loss_input = (-cost_gap * weight).clamp(min=-1e6, max=1e6)\n    pref_scores = ops.logsigmoid(loss_input)\n    return pref_scores.mean()"
